add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_gateways_by_product_type' );

function perfectpixel_gateways_by_product_type( $gateways ) {
	if ( is_admin() || ! function_exists( 'WC' ) || ! WC()->cart ) {
		return $gateways;
	}

	// Product type => gateway IDs to hide. Types: simple, variable, grouped, subscription, variable-subscription…
	$rules = array(
		'subscription'          => array( 'cod', 'bacs' ),
		'variable-subscription' => array( 'cod', 'bacs' ),
	);

	foreach ( WC()->cart->get_cart() as $item ) {
		$product = $item['data'] ?? null;
		if ( ! $product ) {
			continue;
		}
		// Variations report "variation"; use the parent type.
		$type = $product->is_type( 'variation' ) ? WC_Product_Factory::get_product_type( $product->get_parent_id() ) : $product->get_type();
		foreach ( $rules[ $type ] ?? array() as $gateway_id ) {
			unset( $gateways[ $gateway_id ] );
		}
	}

	return $gateways;
}
